"""Topic guides (topics.html and topic-*.html): one page per big theme of Welsh history.

Each topic is T(id, English, Welsh, era colour, picture, one line EN, one line CY, intro EN, intro CY, ...).
The intro is a few short paragraphs in our own words; everything else is gathered from the rest of the site:
  people  = person page slugs (person-<slug>.html)
  reads   = pages to read first (long reads, trails, maps)
  az      = A–Z term ids (a-z.html#az-<id>)
  faq     = quick answer ids (questions.html#q-<id>)
  docs    = key document ids (documents.html#doc-<id>)
  battles = battle ids (battles.html#b-<id>)
  places  = place ids (place-<id>.html)
  ev      = a pattern matched against the English timeline events (title and text) to list them on the page;
  xev     = a pattern for event titles to leave out when `ev` catches something off the subject.
A slug or id that does not exist is skipped, so the lists can be generous.
"""


def T(id, en, cy, era, art, sEn, sCy, iEn, iCy, people=(), reads=(), az=(), faq=(), docs=(), battles=(), places=(), ev=None, xev=None):
    return dict(id=id, en=en, cy=cy, era=era, art=art, sEn=sEn, sCy=sCy, iEn=list(iEn), iCy=list(iCy), people=list(people), reads=list(reads),
                az=list(az), faq=list(faq), docs=list(docs), battles=list(battles), places=list(places), ev=ev, xev=xev)


